from functools import lru_cache
def get_map(qa):
    qc=[(r,c) for r in range(8) for c in range(8) if qa[r][c]!=b]
    tgt={p:qa[p[0]][p[1]] for p in qc}
    src=cells
    # backtracking match src->tgt same color
    import sys
    sys.setrecursionlimit(10000)
    res=[]
    used=set(); m={}
    def bt(i):
        if res: return
        if i==len(src): res.append(dict(m)); return
        r,c,v=src[i]
        for p in qc:
            if p not in used and tgt[p]==v:
                used.add(p); m[(r,c)]=p
                bt(i+1)
                if res: return
                used.discard(p); del m[(r,c)]
    bt(0)
    return res[0] if res else None
